import numpy as np

class WavySphere:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Base sphere function with added periodic waviness
        sphere = np.sum(x**2)
        # Add sinusoidal waves with different frequencies per dimension
        waves = np.sum(np.sin(2 * np.pi * x) * (1 + 0.1 * np.arange(self.dim)))
        return sphere + 0.1 * waves

