import numpy as np

class FractalBasin:
    def __init__(self, dim=5, depth=3):
        self.dim = dim
        self.depth = depth  # Controls the fractal depth/recursion level

    def _recursive_sine(self, x, level=0):
        if level >= self.depth:
            return np.sin(2 * np.pi * x)
        return np.sin(2 * np.pi * x + 0.1 * self._recursive_sine(x, level+1))

    def f(self, x):
        # Base quadratic term
        sphere = np.sum(x**2)

        # Fractal-like local perturbations
        fractal_perturb = 0
        for i in range(self.dim):
            fractal_perturb += self._recursive_sine(x[i], 0)

        return sphere + 0.05 * fractal_perturb

import numpy as np

class FractalBasin:
    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Base quadratic term
        quadratic = np.sum(x**2)

        # Fractal-like perturbation using multiple frequency components
        fractal = 0.0
        for k in range(1, 5):
            fractal += np.sum(np.sin(2**k * np.pi * x)) / (2**k)

        # Combined landscape with decreasing fractal amplitude
        r = np.linalg.norm(x)
        return quadratic + 0.05 * fractal * np.exp(-0.1 * r)
